function fit_kundur_e123_effective_params4()
pf_init_paths; c=cases.case_kundur_two_area_classical(); pf=pfsolver.powerflow_newton_raphson(c,struct('plot_results',false,'verbose',false,'max_iter',50,'tolerance',1e-8,'enforce_q_limits',false)); baseM=c.machines; ref=[-0.111 3.430 0.032; -0.492 6.820 0.072; -0.506 7.020 0.072];
% variables: Tpq0 Tppd0 Tppq0 H12 H34 Xq Xqp Xqpp
p0=log([0.556 0.0358 0.0478 1.014 1.011 1.0 1.0 1.0]); opts=optimset('Display','iter','MaxIter',220,'MaxFunEvals',500,'TolX',1e-5,'TolFun',1e-10); [p,J]=fminsearch(@(p)cost(p,pf,baseM,ref),p0,opts); v=exp(p); fprintf('J=%g Tpq=%.8f Tppd=%.8f Tppq=%.8f H12=%.8f H34=%.8f XqS=%.8f XqpS=%.8f XqppS=%.8f\n',J,v); show(v,pf,baseM,ref);
end
function J=cost(p,pf,baseM,ref); v=exp(p); if any(~isfinite(v))||v(1)<.05||v(1)>2||v(2)<.002||v(2)>.2||v(3)<.002||v(3)>.2||v(4)<.7||v(4)>1.5||v(5)<.7||v(5)>1.5||v(6)<.8||v(6)>1.2||v(7)<.8||v(7)>1.2||v(8)<.8||v(8)>1.2; J=1e6; return; end; try; m=modes(v,pf,baseM); J=0; for k=1:3; scale=[abs(ref(k,1)) ref(k,2) ref(k,3)]; J=J+sum(((m(k,:)-ref(k,:))./scale).^2); end; catch; J=1e6; end; end
function m=modes(v,pf,baseM); M=baseM; M.time_constants.Tpq0=v(1); M.time_constants.Tppd0=v(2); M.time_constants.Tppq0=v(3); for kk=1:2; M.units(kk).H=baseM.units(kk).H*v(4); end; for kk=3:4; M.units(kk).H=baseM.units(kk).H*v(5); end; M.reactances.Xq=baseM.reactances.Xq*v(6); M.reactances.Xqp=baseM.reactances.Xqp*v(7); M.reactances.Xqpp=baseM.reactances.Xqpp*v(8); ssa=stability.kundur_ex126_kundur_ssa('pf',pf,'options',struct('load_model','cc_p_cz_q','machine_override',M)); lam=ssa.eigenvalues(:); osc=lam(abs(imag(lam))>.1&real(lam)<0&imag(lam)>0); [~,idx]=sort(abs(imag(osc))); osc=osc(idx); if numel(osc)<3; error('modes'); end; m=zeros(3,3); for k=1:3; m(k,:)=[real(osc(k)) imag(osc(k)) -real(osc(k))/abs(osc(k))]; end; end
function show(v,pf,baseM,ref); m=modes(v,pf,baseM); for k=1:3; fprintf('m%d %.8f+j%.8f z=%.8f ferr=%.4f%% zerr=%.4f%% reerr=%.4f%%\n',k,m(k,1),m(k,2),m(k,3),abs(m(k,2)-ref(k,2))/ref(k,2)*100,abs(m(k,3)-ref(k,3))/ref(k,3)*100,abs(m(k,1)-ref(k,1))/abs(ref(k,1))*100); end; end
